    achHintCompletionist: 'Unlock every other achievement',
    interactTerminal: 'Press **F** to access terminal',
    loreVireoTerminal: 'SUBJECT LOG 0 - RESTRICTED. "Wellness Light" was never about calm. Sustained exposure suppresses higher brain function while leaving the motor cortex and aggression response intact. We didn\'t cause an outbreak. We manufactured one, city-wide, through every streetlight we \'donated.\' Termination of the program was denied. Continue observation.',
    loreAudiolog1: 'Day 14. Broadcasts stopped this morning. The east water tower is still clean, if anyone finds this.',
    loreAudiolog2: "They don't feel pain - aim for the head or don't bother. Lost Marcus learning that.",
    loreAudiolog3: 'The lookout towers are the safest place to sleep. Just don\'t stay past sunrise.',
    loreAudiolog4: 'Day 31. Found VIREO company badges on three of the collapsed ones near the tower signs. Whatever they were testing in that "wellness light" program, it didn\'t go the way the ads promised.',
    loreAudiolog5: 'Day 47. I keep this camera running so somebody finds proof, if I don\'t make it. The signs still glow at night, don\'t they. VIREO said the light would keep us calm. I think it\'s the opposite.',
    loreAudiolog6: 'Day 52. Still broadcasting from the station every hour, on the hour. No replies in six days. I\'ll keep transmitting anyway - if nobody\'s listening, at least it proves I\'m still alive to send it.',
    loreAudiolog7: 'Day 58. Found a supply cache at the warehouse with a VIREO shipping manifest tucked inside. Same lot numbers as the tower signs. This wasn\'t an accident - someone signed off on shipping it here.',
    loreAudiolog8: 'Day 64. Dug as far down as this mine goes looking for a way out. There isn\'t one. If you\'re reading this, you made it further than I did - that\'s something. Go back up. Don\'t make my mistake.',
    vireoGuardianWakes: 'Something wakes in the dark. The terminal won\'t talk until it stops moving.',
    vireoGuardianAlive: 'The guardian is still alive.',
    loreFlashlightWarning: 'The light... they can feel it. Every zombie for blocks knows exactly where you are.',
