    loreStationTerminal: '运输管理局 —— 线路状态离线。最后一条手动记录,未署名:“列车停运时把这个站台封了,没走正规关闭流程 —— 想着或许有人用得上这块地方。带不走的东西都留在后面的办公室里了。别在这下面待得比必要的更久。”',
