    interactTerminal: '按 **F** 使用终端',
    loreVireoTerminal: '受试者日志 0 —— 机密。“康宁之光”从来就与安宁无关。持续照射会抑制高级脑功能,同时保留运动皮层与攻击性反应。我们没有引发一场疫情,我们制造了一场 —— 通过我们“捐赠”的每一盏路灯,遍布全城。终止该项目的申请被驳回。继续观察。',
    loreAudiolog4: '第 31 天。在塔标附近三具倒下的丧尸身上找到了 VIREO 公司的徽章。不管他们在“康宁之光”项目里测试的是什么,结果都和广告承诺的完全不一样。',
    loreAudiolog5: '第 47 天。我让这台摄像机一直开着,万一我撑不过去,也好让人找到证据。那些标志晚上还在发光,对吧。VIREO 说那光会让我们平静下来。我觉得恰恰相反。',
    loreAudiolog6: '第 52 天。还在每小时整点从电台广播。已经六天没有回音了。我还是会继续发送 —— 就算没人在听,至少能证明我还活着,还能发出这段信号。',
    loreAudiolog7: '第 58 天。在仓库找到一处补给储藏点,里面塞着一份 VIREO 的运货清单。批号和塔标上的一样。这不是意外 —— 有人签字批准把这东西运到这里来。',
    loreAudiolog8: '第 64 天。把这座矿一直挖到了尽头,想找条出路。没有。如果你在读这段话,说明你走得比我更远了 —— 这已经是件了不起的事。回到地面去。别犯我犯过的错。',
    vireoGuardianWakes: '黑暗中有什么东西醒了过来。终端在它停止移动之前不会给出回应。',
    vireoGuardianAlive: '守卫者依然活着。',
    loreFlashlightWarning: '那束光……它们能感觉到。方圆几个街区的每一只丧尸都清楚地知道你在哪里。',
