    interactTerminal: 'टर्मिनल इस्तेमाल करने के लिए **F** दबाएँ',
    loreVireoTerminal: 'सब्जेक्ट लॉग 0 - प्रतिबंधित। "वेलनेस लाइट" कभी शांति के बारे में नहीं थी। लगातार संपर्क में रहने से मस्तिष्क के उच्च कार्य दब जाते हैं, जबकि मोटर कॉर्टेक्स और आक्रामकता प्रतिक्रिया बरकरार रहती है। हमने कोई प्रकोप नहीं फैलाया। हमने इसे बनाया, पूरे शहर में, हर उस स्ट्रीटलाइट के ज़रिए जो हमने \'दान\' की थी। कार्यक्रम बंद करने की माँग ठुकरा दी गई। निगरानी जारी रखें।',
    loreAudiolog4: 'दिन 31। टावर के साइनबोर्ड के पास गिरे तीन लोगों पर VIREO कंपनी के बैज मिले। उस "वेलनेस लाइट" प्रोग्राम में वे जो भी परख रहे थे, वह विज्ञापनों के वादे के मुताबिक नहीं निकला।',
    loreAudiolog5: 'दिन 47। मैं यह कैमरा चालू रखता हूँ ताकि अगर मैं न बचूँ तो किसी को सबूत मिल जाए। साइन अब भी रात में चमकते हैं, है ना। VIREO ने कहा था कि यह रोशनी हमें शांत रखेगी। मुझे लगता है असल में उल्टा है।',
    loreAudiolog6: 'दिन 52। स्टेशन से अब भी हर घंटे, ठीक समय पर, प्रसारण कर रहा हूँ। छह दिनों से कोई जवाब नहीं। फिर भी भेजता रहूँगा - अगर कोई नहीं सुन रहा, तो कम से कम यह साबित तो होता है कि मैं इसे भेजने के लिए अभी ज़िंदा हूँ।',
    loreAudiolog7: 'दिन 58। गोदाम में एक सप्लाई कैश मिला जिसमें अंदर एक VIREO शिपिंग मैनिफेस्ट छिपा था। टावर के साइनबोर्ड जैसे ही लॉट नंबर। यह कोई हादसा नहीं था - किसी ने इसे यहाँ भेजने की मंज़ूरी दी थी।',
    loreAudiolog8: 'दिन 64। रास्ता ढूँढने के लिए इस खदान में जितना नीचे जा सकता था, गया। कोई रास्ता नहीं है। अगर तुम यह पढ़ रहे हो, तो तुम मुझसे आगे निकल चुके हो - यह भी कुछ कम नहीं। वापस ऊपर जाओ। मेरी गलती मत दोहराना।',
    vireoGuardianWakes: 'अंधेरे में कुछ जाग उठता है। जब तक वह हिलना बंद नहीं करता, टर्मिनल कुछ नहीं बताएगा।',
    vireoGuardianAlive: 'गार्जियन अभी भी ज़िंदा है।',
