    loreStationTerminal: 'AUTORIDAD DE TRÁNSITO - ESTADO DE LÍNEA FUERA DE SERVICIO. Último registro manual, sin firmar: "Sellé este andén cuando los trenes dejaron de circular en vez de cerrarlo como es debido - pensé que alguien podría necesitar el espacio. Dejé lo que no pudimos llevarnos en las oficinas del fondo. No te quedes aquí abajo más de lo necesario."',
    stationAmbush: 'Algo hay aquí abajo contigo.',
    dailyTwistSwarm: 'Giro de Hoy: Noche de Enjambre (más zombis)',
    dailyTwistGlassCannon: 'Giro de Hoy: Cañón de Cristal (daño extra recibido)',
