    dailyBest: 'Mejor de hoy: {score}',
    dailyResult: '{twist} - Puntuación: {score} (Mejor de hoy: {best})',
    endingText: 'Encontraste la verdad. VIREO no va a venir a cerrar esto, y las luces no se van a apagar solas. Alguien tiene que seguir sobreviviendo el tiempo suficiente para asegurarse de que la historia salga a la luz. Ahora eres tú.',
    endingCredits: 'GAYZ\nUna Manzana de la Ciudad Rota\n\nHecho con mucha ayuda por el camino.\nGracias por jugar.',
    endingStatSummary: 'Para cuando alguien más oyó la historia, habías sobrevivido {nights} noches, acabado con {kills} de ellos, y sacado con vida a {rescued} personas.',
