    achHintInseparable: 'Llega a la Noche 10 con tu compañero aún en pie',
    achHintTraderConfidant: 'Completa las 3 solicitudes del Comerciante al menos una vez',
    achHintCompletionist: 'Desbloquea todos los demás logros',
    interactTerminal: 'Pulsa **F** para acceder al terminal',
    loreVireoTerminal: 'REGISTRO DE SUJETO 0 - RESTRINGIDO. "Luz del Bienestar" nunca trató de calmar a nadie. La exposición sostenida suprime la función cerebral superior mientras deja intactos la corteza motora y la respuesta de agresión. No causamos un brote. Fabricamos uno, en toda la ciudad, a través de cada farola que "donamos". Se denegó la terminación del programa. Continuar observación.',
    loreAudiolog4: 'Día 31. Encontré insignias de la empresa VIREO en tres de los caídos cerca de los carteles de la torre. Fuera lo que fuera lo que probaban en ese programa de "luz del bienestar", no salió como prometía la publicidad.',
    loreAudiolog5: 'Día 47. Sigo grabando con esta cámara por si alguien encuentra pruebas, si no lo consigo. Los carteles siguen brillando de noche, ¿verdad? VIREO dijo que la luz nos mantendría tranquilos. Creo que es todo lo contrario.',
    loreAudiolog6: 'Día 52. Sigo emitiendo desde la estación cada hora, en punto. Sin respuestas en seis días. Seguiré transmitiendo de todos modos - si nadie escucha, al menos demuestra que sigo vivo para enviarlo.',
    loreAudiolog7: 'Día 58. Encontré un alijo de suministros en el almacén con un manifiesto de envío de VIREO dentro. Los mismos números de lote que los carteles de la torre. Esto no fue un accidente - alguien autorizó que lo enviaran aquí.',
    loreAudiolog8: 'Día 64. Cavé hasta donde llega esta mina buscando una salida. No la hay. Si estás leyendo esto, llegaste más lejos que yo - eso ya es algo. Vuelve arriba. No cometas mi error.',
    vireoGuardianWakes: 'Algo despierta en la oscuridad. El terminal no hablará hasta que deje de moverse.',
    vireoGuardianAlive: 'El guardián sigue vivo.',
