    loreAudiolog2: 'వాటికి నొప్పి తెలియదు — తలపై గురిపెట్టండి లేదా ప్రయత్నించకండి. అది నేర్చుకుంటూ మార్కస్‌ను కోల్పోయాను.',
    loreAudiolog3: 'పరిశీలన గోపురాలు నిద్రించడానికి అత్యంత సురక్షితమైన ప్రదేశం. సూర్యోదయం తర్వాత మాత్రం ఉండకండి.',
